"""Leaderboard aggregation: pivot, mean, win-rate, bootstrap CI, markdown.

Conceptual references:
- ./docs/en.md (this lesson)
- lesson 71 (classical metrics) for per-task score shape
- lesson 73 (calibration) for the multi-model report pattern

Stdlib + numpy. Run: python3 code/main.py
"""

from __future__ import annotations

import json
import math
import sys
from collections import defaultdict
from dataclasses import dataclass, field
from typing import Iterable, Sequence

import numpy as np


@dataclass
class EvalRun:
    model_id: str
    task_id: str
    metric_name: str
    score: float
    category: str = "general"
    weight: float = 1.0


@dataclass
class LeaderboardRow:
    model_id: str
    mean_score: float
    mean_ci_lo: float
    mean_ci_hi: float
    win_rate: float
    tasks_completed: int
    categories: dict[str, float] = field(default_factory=dict)

    def to_dict(self) -> dict:
        return {
            "model_id": self.model_id,
            "mean_score": self.mean_score,
            "mean_ci_lo": self.mean_ci_lo,
            "mean_ci_hi": self.mean_ci_hi,
            "win_rate": self.win_rate,
            "tasks_completed": self.tasks_completed,
            "categories": dict(self.categories),
        }


@dataclass
class PairwiseDiff:
    model_a: str
    model_b: str
    diff_mean: float
    ci_lo: float
    ci_hi: float
    significant: bool

    def to_dict(self) -> dict:
        return {
            "model_a": self.model_a,
            "model_b": self.model_b,
            "diff_mean": self.diff_mean,
            "ci_lo": self.ci_lo,
            "ci_hi": self.ci_hi,
            "significant": self.significant,
        }


def _validate_runs(runs: Sequence[EvalRun]) -> None:
    seen: set[tuple[str, str]] = set()
    for r in runs:
        if not (0.0 <= r.score <= 1.0):
            raise ValueError(f"score for {r.model_id}/{r.task_id} not in [0,1]: {r.score}")
        key = (r.model_id, r.task_id)
        if key in seen:
            raise ValueError(f"duplicate run for {r.model_id}/{r.task_id}")
        seen.add(key)


def _by_model(runs: Sequence[EvalRun]) -> dict[str, list[EvalRun]]:
    out: dict[str, list[EvalRun]] = defaultdict(list)
    for r in runs:
        out[r.model_id].append(r)
    return dict(out)


def _by_task(runs: Sequence[EvalRun]) -> dict[str, list[EvalRun]]:
    out: dict[str, list[EvalRun]] = defaultdict(list)
    for r in runs:
        out[r.task_id].append(r)
    return dict(out)


def bootstrap_mean_ci(
    scores: Sequence[float],
    b: int = 1000,
    alpha: float = 0.05,
    seed: int = 0,
) -> tuple[float, float]:
    if len(scores) == 0:
        return (0.0, 0.0)
    rng = np.random.default_rng(seed)
    arr = np.asarray(scores, dtype=np.float64)
    n = arr.size
    means = np.empty(b, dtype=np.float64)
    for i in range(b):
        idx = rng.integers(0, n, size=n)
        means[i] = float(arr[idx].mean())
    lo = float(np.percentile(means, 100.0 * (alpha / 2.0)))
    hi = float(np.percentile(means, 100.0 * (1.0 - alpha / 2.0)))
    return (lo, hi)


def bootstrap_pairwise_diff(
    paired_a: Sequence[float],
    paired_b: Sequence[float],
    b: int = 1000,
    alpha: float = 0.05,
    seed: int = 0,
) -> tuple[float, float, float]:
    if len(paired_a) != len(paired_b):
        raise ValueError("paired arrays must align")
    if len(paired_a) == 0:
        return (0.0, 0.0, 0.0)
    rng = np.random.default_rng(seed)
    a = np.asarray(paired_a, dtype=np.float64)
    b_arr = np.asarray(paired_b, dtype=np.float64)
    diffs = a - b_arr
    diff_mean = float(diffs.mean())
    n = diffs.size
    boots = np.empty(b, dtype=np.float64)
    for i in range(b):
        idx = rng.integers(0, n, size=n)
        boots[i] = float(diffs[idx].mean())
    lo = float(np.percentile(boots, 100.0 * (alpha / 2.0)))
    hi = float(np.percentile(boots, 100.0 * (1.0 - alpha / 2.0)))
    return (diff_mean, lo, hi)


def _win_rate(model_id: str, runs_by_task: dict[str, list[EvalRun]]) -> tuple[float, int]:
    wins = 0
    total = 0
    for task_id, runs in runs_by_task.items():
        scores = {r.model_id: r.score for r in runs}
        if model_id not in scores:
            continue
        total += 1
        best = max(scores.values())
        if math.isclose(scores[model_id], best, abs_tol=1e-12):
            wins += 1
    if total == 0:
        return (0.0, 0)
    return (wins / total, total)


def _category_means(runs: Sequence[EvalRun]) -> dict[str, float]:
    by_cat: dict[str, list[float]] = defaultdict(list)
    for r in runs:
        by_cat[r.category].append(r.score)
    return {cat: float(np.mean(scores)) for cat, scores in by_cat.items()}


def aggregate(
    runs: Sequence[EvalRun],
    b: int = 500,
    alpha: float = 0.05,
    seed: int = 0,
) -> list[LeaderboardRow]:
    if not runs:
        return []
    _validate_runs(runs)
    by_model = _by_model(runs)
    by_task = _by_task(runs)
    rows: list[LeaderboardRow] = []
    for model_id, model_runs in by_model.items():
        scores = [r.score for r in model_runs]
        mean_score = float(np.mean(scores))
        lo, hi = bootstrap_mean_ci(scores, b=b, alpha=alpha, seed=seed)
        wr, completed = _win_rate(model_id, by_task)
        cats = _category_means(model_runs)
        rows.append(
            LeaderboardRow(
                model_id=model_id,
                mean_score=mean_score,
                mean_ci_lo=lo,
                mean_ci_hi=hi,
                win_rate=wr,
                tasks_completed=completed if completed else len(scores),
                categories=cats,
            )
        )
    rows.sort(key=lambda r: r.mean_score, reverse=True)
    return rows


def pairwise_diffs(
    runs: Sequence[EvalRun],
    b: int = 500,
    alpha: float = 0.05,
    seed: int = 0,
) -> list[PairwiseDiff]:
    if not runs:
        return []
    _validate_runs(runs)
    by_model = _by_model(runs)
    model_ids = sorted(by_model.keys())
    common_task_scores: dict[str, dict[str, float]] = defaultdict(dict)
    for r in runs:
        common_task_scores[r.task_id][r.model_id] = r.score
    out: list[PairwiseDiff] = []
    for i in range(len(model_ids)):
        for j in range(i + 1, len(model_ids)):
            a, b_id = model_ids[i], model_ids[j]
            paired_a = []
            paired_b = []
            for task_id, ms in common_task_scores.items():
                if a in ms and b_id in ms:
                    paired_a.append(ms[a])
                    paired_b.append(ms[b_id])
            if not paired_a:
                continue
            diff_mean, lo, hi = bootstrap_pairwise_diff(paired_a, paired_b, b=b, alpha=alpha, seed=seed + i + j)
            significant = lo > 0.0 or hi < 0.0
            out.append(PairwiseDiff(
                model_a=a,
                model_b=b_id,
                diff_mean=diff_mean,
                ci_lo=lo,
                ci_hi=hi,
                significant=significant,
            ))
    return out


def render_markdown(rows: Sequence[LeaderboardRow]) -> str:
    header = "| Rank | Model | Mean | 95% CI | Win rate | Tasks |"
    sep = "|------|-------|------|--------|----------|-------|"
    out_lines = [header, sep]
    for i, row in enumerate(rows, start=1):
        model_label = row.model_id[:20]
        ci = f"{row.mean_ci_lo:.2f}-{row.mean_ci_hi:.2f}"
        out_lines.append(
            f"| {i} | {model_label} | {row.mean_score:.2f} | {ci} | {row.win_rate:.2f} | {row.tasks_completed} |"
        )
    return "\n".join(out_lines)


def render_json(rows: Sequence[LeaderboardRow]) -> str:
    return json.dumps([r.to_dict() for r in rows], indent=2)


def _synthetic_runs(seed: int = 0) -> list[EvalRun]:
    rng = np.random.default_rng(seed)
    models = ["model_a", "model_b", "model_c"]
    categories = ["arithmetic", "mcq", "code_exec", "summary"]
    runs: list[EvalRun] = []
    means = {"model_a": 0.78, "model_b": 0.72, "model_c": 0.55}
    for cat in categories:
        for t in range(3):
            task_id = f"{cat}_{t:02d}"
            for m in models:
                base = means[m]
                if cat == "code_exec":
                    base -= 0.1
                if cat == "summary" and m == "model_c":
                    base += 0.15
                noise = rng.uniform(-0.1, 0.1)
                score = float(np.clip(base + noise, 0.0, 1.0))
                metric = {"arithmetic": "exact_match", "mcq": "accuracy", "code_exec": "code_exec", "summary": "rouge_l"}[cat]
                runs.append(EvalRun(model_id=m, task_id=task_id, metric_name=metric, score=score, category=cat))
    return runs


def demo() -> int:
    runs = _synthetic_runs(seed=42)
    rows = aggregate(runs, b=300, alpha=0.05, seed=11)
    diffs = pairwise_diffs(runs, b=300, alpha=0.05, seed=11)
    print(render_markdown(rows))
    print()
    print("Pairwise comparisons (paired bootstrap):")
    for d in diffs:
        sig = "yes" if d.significant else "no"
        print(f"  {d.model_a} vs {d.model_b}: diff={d.diff_mean:+.3f} ci=[{d.ci_lo:+.3f},{d.ci_hi:+.3f}] significant={sig}")
    if not rows:
        return 1
    if rows[0].mean_score < rows[-1].mean_score:
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(demo())

// Lesson: Leaderboard Aggregation (phase 19 / lesson 74)
// TypeScript port of code/main.py. Node standard library only.
// Source: phases/19-capstone-projects/74-leaderboard-aggregation/docs/en.md
// Run: npx tsx phases/19-capstone-projects/74-leaderboard-aggregation/code/main.ts

export class EvalRun {
  constructor(
    public model_id: string,
    public task_id: string,
    public metric_name: string,
    public score: number,
    public category = "general",
    public weight = 1.0,
  ) {}
}

export class LeaderboardRow {
  constructor(
    public model_id: string,
    public mean_score: number,
    public mean_ci_lo: number,
    public mean_ci_hi: number,
    public win_rate: number,
    public tasks_completed: number,
    public categories: Record<string, number> = {},
  ) {}

  toDict(): Record<string, unknown> {
    return {
      model_id: this.model_id,
      mean_score: this.mean_score,
      mean_ci_lo: this.mean_ci_lo,
      mean_ci_hi: this.mean_ci_hi,
      win_rate: this.win_rate,
      tasks_completed: this.tasks_completed,
      categories: { ...this.categories },
    };
  }
}

export class PairwiseDiff {
  constructor(
    public model_a: string,
    public model_b: string,
    public diff_mean: number,
    public ci_lo: number,
    public ci_hi: number,
    public significant: boolean,
  ) {}

  toDict(): Record<string, unknown> {
    return {
      model_a: this.model_a,
      model_b: this.model_b,
      diff_mean: this.diff_mean,
      ci_lo: this.ci_lo,
      ci_hi: this.ci_hi,
      significant: this.significant,
    };
  }
}

class Mulberry32 {
  private state: number;

  constructor(seed: number) {
    this.state = seed >>> 0;
  }

  random(): number {
    this.state = (this.state + 0x6d2b79f5) >>> 0;
    let t = this.state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  }

  integer(lo: number, hi: number): number {
    return lo + Math.floor(this.random() * (hi - lo));
  }

  uniform(lo: number, hi: number): number {
    return lo + (hi - lo) * this.random();
  }
}

function mean(values: number[]): number {
  let s = 0.0;
  for (const v of values) s += v;
  return s / values.length;
}

function percentile(values: number[], q: number): number {
  const sorted = [...values].sort((a, b) => a - b);
  const pos = ((sorted.length - 1) * q) / 100.0;
  const lo = Math.floor(pos);
  const hi = Math.min(lo + 1, sorted.length - 1);
  const frac = pos - lo;
  return sorted[lo] + (sorted[hi] - sorted[lo]) * frac;
}

function validateRuns(runs: EvalRun[]): void {
  const seen = new Set<string>();
  for (const r of runs) {
    if (!(r.score >= 0.0 && r.score <= 1.0)) throw new Error(`score for ${r.model_id}/${r.task_id} not in [0,1]: ${r.score}`);
    const key = JSON.stringify([r.model_id, r.task_id]);
    if (seen.has(key)) throw new Error(`duplicate run for ${r.model_id}/${r.task_id}`);
    seen.add(key);
  }
}

function groupBy(runs: EvalRun[], key: (r: EvalRun) => string): Map<string, EvalRun[]> {
  const out = new Map<string, EvalRun[]>();
  for (const r of runs) {
    const k = key(r);
    const list = out.get(k);
    if (list) list.push(r);
    else out.set(k, [r]);
  }
  return out;
}

export function bootstrapMeanCi(scores: number[], b = 1000, alpha = 0.05, seed = 0): [number, number] {
  if (!scores.length) return [0.0, 0.0];
  const rng = new Mulberry32(seed);
  const n = scores.length;
  const means: number[] = [];
  for (let i = 0; i < b; i++) {
    const sample: number[] = [];
    for (let k = 0; k < n; k++) sample.push(scores[rng.integer(0, n)]);
    means.push(mean(sample));
  }
  return [percentile(means, 100.0 * (alpha / 2.0)), percentile(means, 100.0 * (1.0 - alpha / 2.0))];
}

export function bootstrapPairwiseDiff(pairedA: number[], pairedB: number[], b = 1000, alpha = 0.05, seed = 0): [number, number, number] {
  if (pairedA.length !== pairedB.length) throw new Error("paired arrays must align");
  if (!pairedA.length) return [0.0, 0.0, 0.0];
  const rng = new Mulberry32(seed);
  const diffs = pairedA.map((a, i) => a - pairedB[i]);
  const diffMean = mean(diffs);
  const n = diffs.length;
  const boots: number[] = [];
  for (let i = 0; i < b; i++) {
    const sample: number[] = [];
    for (let k = 0; k < n; k++) sample.push(diffs[rng.integer(0, n)]);
    boots.push(mean(sample));
  }
  return [diffMean, percentile(boots, 100.0 * (alpha / 2.0)), percentile(boots, 100.0 * (1.0 - alpha / 2.0))];
}

function winRate(modelId: string, runsByTask: Map<string, EvalRun[]>): [number, number] {
  let wins = 0;
  let total = 0;
  for (const runs of runsByTask.values()) {
    const scores = new Map(runs.map((r) => [r.model_id, r.score]));
    if (!scores.has(modelId)) continue;
    total += 1;
    const best = Math.max(...scores.values());
    const score = scores.get(modelId) as number;
    if (Math.abs(score - best) <= Math.max(1e-9 * Math.max(Math.abs(score), Math.abs(best)), 1e-12)) wins += 1;
  }
  if (total === 0) return [0.0, 0];
  return [wins / total, total];
}

function categoryMeans(runs: EvalRun[]): Record<string, number> {
  const out: Record<string, number> = {};
  for (const [cat, rs] of groupBy(runs, (r) => r.category)) out[cat] = mean(rs.map((r) => r.score));
  return out;
}

export function aggregate(runs: EvalRun[], b = 500, alpha = 0.05, seed = 0): LeaderboardRow[] {
  if (!runs.length) return [];
  validateRuns(runs);
  const byModel = groupBy(runs, (r) => r.model_id);
  const byTask = groupBy(runs, (r) => r.task_id);
  const rows: LeaderboardRow[] = [];
  for (const [modelId, modelRuns] of byModel) {
    const scores = modelRuns.map((r) => r.score);
    const [lo, hi] = bootstrapMeanCi(scores, b, alpha, seed);
    const [wr, completed] = winRate(modelId, byTask);
    rows.push(new LeaderboardRow(modelId, mean(scores), lo, hi, wr, completed ? completed : scores.length, categoryMeans(modelRuns)));
  }
  rows.sort((x, y) => y.mean_score - x.mean_score);
  return rows;
}

export function pairwiseDiffs(runs: EvalRun[], b = 500, alpha = 0.05, seed = 0): PairwiseDiff[] {
  if (!runs.length) return [];
  validateRuns(runs);
  const modelIds = [...groupBy(runs, (r) => r.model_id).keys()].sort();
  const common = new Map<string, Map<string, number>>();
  for (const r of runs) {
    let ms = common.get(r.task_id);
    if (!ms) {
      ms = new Map();
      common.set(r.task_id, ms);
    }
    ms.set(r.model_id, r.score);
  }
  const out: PairwiseDiff[] = [];
  for (let i = 0; i < modelIds.length; i++) {
    for (let j = i + 1; j < modelIds.length; j++) {
      const a = modelIds[i];
      const bId = modelIds[j];
      const pairedA: number[] = [];
      const pairedB: number[] = [];
      for (const ms of common.values()) {
        if (ms.has(a) && ms.has(bId)) {
          pairedA.push(ms.get(a) as number);
          pairedB.push(ms.get(bId) as number);
        }
      }
      if (!pairedA.length) continue;
      const [diffMean, lo, hi] = bootstrapPairwiseDiff(pairedA, pairedB, b, alpha, seed + i + j);
      out.push(new PairwiseDiff(a, bId, diffMean, lo, hi, lo > 0.0 || hi < 0.0));
    }
  }
  return out;
}

export function renderMarkdown(rows: LeaderboardRow[]): string {
  const lines = ["| Rank | Model | Mean | 95% CI | Win rate | Tasks |", "|------|-------|------|--------|----------|-------|"];
  rows.forEach((row, i) => {
    const label = [...row.model_id].slice(0, 20).join("");
    const ci = `${row.mean_ci_lo.toFixed(2)}-${row.mean_ci_hi.toFixed(2)}`;
    lines.push(`| ${i + 1} | ${label} | ${row.mean_score.toFixed(2)} | ${ci} | ${row.win_rate.toFixed(2)} | ${row.tasks_completed} |`);
  });
  return lines.join("\n");
}

export function renderJson(rows: LeaderboardRow[]): string {
  return JSON.stringify(
    rows.map((r) => r.toDict()),
    null,
    2,
  );
}

export function signed(x: number, digits: number): string {
  const s = x.toFixed(digits);
  return s.startsWith("-") ? s : "+" + s;
}

function syntheticRuns(seed = 0): EvalRun[] {
  const rng = new Mulberry32(seed);
  const models = ["model_a", "model_b", "model_c"];
  const categories = ["arithmetic", "mcq", "code_exec", "summary"];
  const means: Record<string, number> = { model_a: 0.78, model_b: 0.72, model_c: 0.55 };
  const metrics: Record<string, string> = { arithmetic: "exact_match", mcq: "accuracy", code_exec: "code_exec", summary: "rouge_l" };
  const runs: EvalRun[] = [];
  for (const cat of categories) {
    for (let t = 0; t < 3; t++) {
      const taskId = `${cat}_${String(t).padStart(2, "0")}`;
      for (const m of models) {
        let base = means[m];
        if (cat === "code_exec") base -= 0.1;
        if (cat === "summary" && m === "model_c") base += 0.15;
        const noise = rng.uniform(-0.1, 0.1);
        const score = Math.min(1.0, Math.max(0.0, base + noise));
        runs.push(new EvalRun(m, taskId, metrics[cat], score, cat));
      }
    }
  }
  return runs;
}

export function demo(): number {
  const runs = syntheticRuns(42);
  const rows = aggregate(runs, 300, 0.05, 11);
  const diffs = pairwiseDiffs(runs, 300, 0.05, 11);
  console.log(renderMarkdown(rows));
  console.log();
  console.log("Pairwise comparisons (paired bootstrap):");
  for (const d of diffs) {
    const sig = d.significant ? "yes" : "no";
    console.log(
      `  ${d.model_a} vs ${d.model_b}: diff=${signed(d.diff_mean, 3)} ci=[${signed(d.ci_lo, 3)},${signed(d.ci_hi, 3)}] significant=${sig}`,
    );
  }
  if (!rows.length) return 1;
  if (rows[0].mean_score < rows[rows.length - 1].mean_score) return 1;
  return 0;
}

if (require.main === module) {
  process.exitCode = demo();
}
